fragments.css:
.navbar_link { color: var(--neutral--lighter); text-decoration: none; font-size: .9375rem; padding: .5rem 0; border-bottom: 1px solid transparent; transition: color .2s,border-color .2s }
.navbar_link:hover { color: var(--neutral--white); border-bottom-color: var(--christine--primary) }
.navbar_phone { color: var(--neutral--white); text-decoration: none; font-family: var(--font--heading); font-size: .8125rem }
.navbar_phone:hover { color: var(--christine--light) }
.navbar_button { display: inline-flex; align-items: center; justify-content: center; gap: .5rem; min-height: 2.75rem; padding: 0 1.25rem; border-radius: 100px; background-color: var(--christine--primary); color: var(--neutral--darkest); font-weight: 600; font-size: .9375rem; text-decoration: none; transition: background-color .2s,transform .16s cubic-bezier(.23,1,.32,1); touch-action: manipulation }
.navbar_button:hover { background-color: var(--christine--light); color: var(--neutral--darkest) }
.navbar_skip { position: absolute; left: 1rem; top: -4rem; z-index: 20; padding: .75rem 1rem; border-radius: 12px; background-color: var(--christine--primary); color: var(--neutral--darkest); font-weight: 600; text-decoration: none; transition: top .2s }
.navbar_skip:focus { top: 1rem; color: var(--neutral--darkest) }
.navbar_button:active { transform: scale(.97) }
.navbar_component { position: relative; z-index: 10; background-color: var(--neutral--darker); color: var(--neutral--white); font-family: var(--font--body); border-bottom: 1px solid rgba(255,255,255,.12) }
.navbar_container { max-width: 80rem; margin: 0 auto; min-height: 5.5rem; padding: .75rem 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .75rem 2rem }
.navbar_logo-link { display: flex; align-items: center }
.navbar_logo { width: 197px; height: 44px }
.navbar_menu { display: flex; flex-wrap: wrap; align-items: center; gap: .25rem 2rem }
.navbar_actions { display: flex; align-items: center; gap: 1.5rem }
@media screen and (max-width: 991px) { .navbar_phone { display: none } }
@media screen and (max-width: 479px) { .navbar_logo { width: 162px; height: 36px } }
